<!DOCTYPE html><html lang="ro"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="robots" content="noindex, nofollow"><meta name="theme-color" content="#061a15"><title>Preferințe și notificări — Nordvale</title><meta name="description" content="Controlează alertele, canalele și frecvența comunicărilor Nordvale."><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&display=swap" rel="stylesheet"><style>
    :root{--pine-950:#061a15;--pine-900:#09251d;--pine-850:#0d3027;--pine-800:#123b30;--pine-700:#1b5242;--acid:#dffc62;--ember:#f27b4a;--cream:#fffdf6;--oat:#f0ecdf;--moss:#b7c9a3;--ink:#16231e;--muted:rgba(22,35,30,.58);--line:rgba(9,37,29,.12);--shadow:0 28px 80px -48px rgba(6,26,21,.62);--card-shadow:0 20px 54px -38px rgba(6,26,21,.48)}
