    .site-header{position:sticky;top:0;z-index:50;padding:12px 0;background:linear-gradient(180deg,rgba(240,236,223,.96),rgba(240,236,223,.78),transparent)}.nav{display:flex;align-items:center;gap:16px;padding:10px 12px 10px 16px;border:1px solid rgba(255,255,255,.12);border-radius:22px;background:rgba(6,26,21,.89);box-shadow:0 24px 70px -46px rgba(0,0,0,.9);backdrop-filter:blur(22px) saturate(130%);color:#fff}.brand{display:flex;align-items:center;gap:11px;min-width:0}.brand-mark{display:grid;place-items:center;width:42px;height:42px;flex:0 0 auto;border:1px solid rgba(223,252,98,.42);border-radius:15px;background:rgba(223,252,98,.08);color:var(--acid)}.brand-copy{min-width:0;line-height:1}.brand-copy strong{display:block;font-family:"Fraunces",serif;font-size:18px;font-weight:600;letter-spacing:-.02em}.brand-copy span{display:block;margin-top:5px;color:rgba(255,255,255,.5);font-size:10px;font-weight:700;letter-spacing:.18em;text-transform:uppercase;white-space:nowrap}.main-nav{display:flex;align-items:center;gap:6px;margin-left:auto}.main-nav a{padding:10px 12px;border-radius:12px;color:rgba(255,255,255,.68);font-size:13px;font-weight:600}.main-nav a:hover{background:rgba(255,255,255,.07);color:#fff}.nav-actions{display:flex;align-items:center;gap:8px}.ticket-cta{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border-radius:13px;background:var(--acid);color:var(--pine-950);font-size:13px;font-weight:800;white-space:nowrap}.menu-btn{display:none;place-items:center;width:40px;height:40px;border:0;border-radius:13px;background:rgba(255,255,255,.07);color:#fff;cursor:pointer}
    .layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:24px;padding:18px 0 96px}.sidebar{position:sticky;top:92px;align-self:start;padding:18px;border:1px solid var(--line);border-radius:26px;background:rgba(255,253,246,.8);box-shadow:var(--card-shadow);backdrop-filter:blur(18px)}.profile-mini{display:flex;align-items:center;gap:12px;padding:8px 8px 20px;border-bottom:1px solid var(--line)}.avatar{position:relative;display:grid;place-items:center;width:50px;height:50px;flex:0 0 auto;border-radius:18px;background:var(--pine-900);color:var(--acid);font-family:"Fraunces",serif;font-size:18px;font-weight:700}.avatar:after{content:"";position:absolute;right:-2px;bottom:-2px;width:13px;height:13px;border:3px solid var(--cream);border-radius:50%;background:#54c97a}.profile-mini strong{display:block;font-size:14px}.profile-mini span span{display:block;margin-top:4px;color:rgba(22,35,30,.54);font-size:11px}.side-nav{display:grid;gap:6px;padding:16px 0}.side-nav a{display:flex;align-items:center;gap:11px;padding:11px 12px;border-radius:14px;color:rgba(22,35,30,.64);font-size:13px;font-weight:650;transition:.2s ease}.side-nav a:hover{background:rgba(9,37,29,.06);color:var(--pine-900)}.side-nav a.active{background:var(--pine-900);color:#fff}.side-nav svg{width:18px;height:18px;flex:0 0 auto}.side-help{padding:15px;border-radius:18px;background:var(--oat)}.side-help strong{display:block;font-family:"Fraunces",serif;font-size:17px}.side-help p{margin:7px 0 12px;color:rgba(22,35,30,.6);font-size:11px;line-height:1.55}.side-help a{color:var(--pine-900);font-size:12px;font-weight:800}
    .content{min-width:0}.hero{position:relative;overflow:hidden;display:grid;grid-template-columns:minmax(0,1fr) 360px;min-height:330px;border-radius:34px;background:var(--pine-900);color:#fff;box-shadow:var(--shadow)}.hero-copy{position:relative;z-index:3;display:flex;flex-direction:column;justify-content:center;padding:40px 44px}.eyebrow{display:inline-flex;align-items:center;gap:8px;width:max-content;padding:7px 10px;border:1px solid rgba(223,252,98,.22);border-radius:999px;background:rgba(223,252,98,.08);color:var(--acid);font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.eyebrow-dot{width:7px;height:7px;border-radius:50%;background:var(--acid);box-shadow:0 0 0 7px rgba(223,252,98,.1)}.hero h1{margin:20px 0 12px;font-family:"Fraunces",serif;font-size:clamp(40px,4.6vw,66px);font-weight:600;letter-spacing:-.055em;line-height:.98}.hero h1 em{color:var(--acid);font-style:italic}.hero-copy>p{max-width:650px;margin:0;color:rgba(255,255,255,.66);font-size:15px;line-height:1.7}.completion{display:flex;align-items:center;gap:16px;margin-top:24px}.completion-ring{--value:82;position:relative;display:grid;place-items:center;width:62px;height:62px;border-radius:50%;background:conic-gradient(var(--acid) calc(var(--value)*1%),rgba(255,255,255,.12) 0)}.completion-ring:before{content:"";position:absolute;inset:6px;border-radius:50%;background:var(--pine-900)}.completion-ring strong{position:relative;z-index:2;font-size:14px}.completion span strong{display:block;font-size:13px}.completion span small{display:block;margin-top:4px;color:rgba(255,255,255,.52);font-size:11px}.hero-visual{position:relative;display:grid;place-items:center;min-height:330px;padding:28px}.hero-visual:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,var(--pine-900),rgba(9,37,29,.18) 38%,rgba(9,37,29,.08)),url("https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1100&q=86") center/cover;opacity:.76}.profile-card{position