    .tabs{position:sticky;top:87px;z-index:18;display:flex;gap:6px;margin:16px 0;padding:7px;border:1px solid var(--line);border-radius:18px;background:rgba(240,236,223,.88);backdrop-filter:blur(18px);overflow-x:auto;scrollbar-width:none}.tabs::-webkit-scrollbar{display:none}.tabs button{flex:0 0 auto;min-height:40px;padding:0 14px;border:0;border-radius:12px;background:transparent;color:var(--muted);cursor:pointer;font-size:12px;font-weight:800;white-space:nowrap}.tabs button.active{background:var(--pine-900);color:#fff}.section-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(300px,.75fr);gap:16px}.stack{display:grid;gap:16px}.card{padding:24px;border:1px solid var(--line);border-radius:27px;background:var(--cream);box-shadow:var(--card-shadow)}.card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:22px}.card-kicker{margin:0 0 7px;color:var(--pine-700);font-size:9px;font-weight:900;letter-spacing:.16em;text-transform:uppercase}.card h2,.card h3{margin:0;font-family:"Fraunces",serif;font-weight:600;letter-spacing:-.025em}.card h2{font-size:26px}.card h3{font-size:21px}.card-head p:not(.card-kicker){max-width:520px;margin:7px 0 0;color:var(--muted);font-size:12px;line-height:1.55}.status-pill{display:inline-flex;align-items:center;gap:7px;flex:0 0 auto;padding:8px 10px;border-radius:999px;background:rgba(84,201,122,.11);color:#257344;font-size:10px;font-weight:900}.status-pill:before{content:"";width:7px;height:7px;border-radius:50%;background:#54c97a}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.field{display:grid;gap:7px}.field.full{grid-column:1/-1}.field label{font-size:11px;font-weight:800}.field small{color:var(--muted);font-size:10px}.control{width:100%;min-height:48px;padding:0 14px;border:1px solid var(--line);border-radius:14px;background:#fff;color:var(--ink);outline:none;transition:.2s ease}.control:focus{border-color:rgba(9,37,29,.42);box-shadow:0 0 0 4px rgba(