rder:1px solid var(--line);border-radius:17px;background:#fff}.item-icon{display:grid;place-items:center;width:40px;height:40px;flex:0 0 auto;border-radius:13px;background:var(--oat);color:var(--pine-800)}.item-copy{min-width:0;margin-right:auto}.item-copy strong{display:block;font-size:12px}.item-copy span{display:block;margin-top:4px;color:var(--muted);font-size:10px;line-height:1.4}.text-btn{padding:7px 0;border:0;background:transparent;color:var(--pine-700);cursor:pointer;font-size:10px;font-weight:900;white-space:nowrap}.progress-card{background:var(--pine-900);color:#fff}.progress-card p{color:rgba(255,255,255,.58)}.progress-track{height:8px;margin:18px 0 10px;border-radius:999px;background:rgba(255,255,255,.1);overflow:hidden}.progress-track span{display:block;width:82%;height:100%;border-radius:inherit;background:var(--acid)}.checklist{display:grid;gap:10px;margin-top:18px}.check-item{display:flex;align-items:center;gap:9px;font-size:11px}.check-dot{display:grid;place-items:center;width:22px;height:22px;border-radius:8px;background:rgba(223,252,98,.12);color:var(--acid)}.check-item.missing .check-dot{background:rgba(242,123,74,.13);color:var(--ember)}.session{display:flex;align-items:center;gap:12px;padding:13px 0;border-bottom:1px solid var(--line)}.session:last-child{border-bottom:0}.session-device{display:grid;place-items:center;width:38px;height:38px;border-radius:13px;background:var(--oat)}.session strong{display:block;font-size:11px}.session span{display:block;margin-top:3px;color:var(--muted);font-size:9px}.session-current{margin-left:auto;color:#257344;font-size:9px;font-weight:900}
    .mobile-nav{display:none;position:fixed;z-index:45;left:10px;right:10px;bottom:max(10px,env(safe-area-inset-bottom));grid-template-columns:repeat(5,1fr);padding:7px;border:1px solid rgba(255,255,255,.12);border-radius:20px;background:rgba(6,26,21,.94);box-shadow:0 24px 70px -30px rgba(0,0,0,.76);backdrop-filter:blur(20px);color:#fff}.mobile-nav a{display:grid;place-items:center;gap:4px;padding:7px 2px;border-radius:13px;color:rgba(255,255,255,.52);font-size:8px;font-weight:800}.mobile-nav a.active{background:rgba(223,252,98,.12);color:var(--acid)}.mobile-nav svg{width:17px;height:17px}.mobile-menu{position:fixed;z-index:70;inset:0;display:grid;align-content:start;padding:18px;background:var(--pine-950);color:#fff;transform:translateY(-105%);transition:.34s cubic-bezier(.22,.8,.2,1)}.mobile-menu.open{transform:translateY(0)}.mobile-menu-head{display:flex;align-items:center;justify-content:space-between}.mobile-menu-links{display:grid;gap:8px;margin-top:45px}.mobile-menu-links a{padding:16px 4px;border-bottom:1px solid rgba(255,255,255,.1);font-family:"Fraunces",serif;font-size:26px}.modal{position:fixed;z-index:80;inset:0;display:grid;place-items:center;padding:18px;background:rgba(6,26,21,.72);backdrop-filter:blur(13px);opacity:0;pointer-events:none;transition:.22s ease}.modal.open{opacity:1;pointer-events:auto}.modal-card{position:relative;width:min(540px,100%);max-height:min(760px,calc(100vh - 36px));overflow:auto;padding:27px;border-radius:28px;background:var(--cream);box-shadow:0 40px 100px -45px #000}.modal-close{display:grid;place-items:center;width:38px;height:38px;border:0;border-radius:13px;background:var(--oat);color:var(--pine-900);cursor:pointer}.modal-card>.modal-close{position:absolute;right:18px;top:18px}.modal-card h3{margin:10px 0 8px;font-family:"Fraunces",serif;font-size:28px}.modal-card>p{margin:0 38px 20px 0;color:var(--muted);font-size:12px;line-height:1.55}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}.danger