    @media(max-width:1120px){.main-nav{display:none}.menu-btn{display:grid}.layout{grid-template-columns:220px minmax(0,1fr)}.hero{grid-template-columns:minmax(0,1fr) 300px}.section-grid{grid-template-columns:1fr}.aside-stack{grid-template-columns:repeat(2,minmax(0,1fr));display:grid;gap:16px}}
    @media(max-width:820px){.shell{width:min(100% - 22px,760px)}.site-header{padding:8px 0}.nav{border-radius:18px;padding:8px 9px 8px 12px}.brand-copy span{display:none}.ticket-cta{min-height:38px;padding:0 12px}.layout{display:block;padding-top:10px}.sidebar{display:none}.hero{display:block;min-height:0;border-radius:27px}.hero-copy{padding:34px 24px 26px}.hero-visual{min-height:285px;padding:24px}.profile-card{width:min(290px,86%)}.tabs{top:71px;margin:12px 0}.mobile-nav{display:grid}.content{padding-bottom:64px}.aside-stack{grid-template-columns:1fr}}
