<script>(()=>{'use strict';const $=(s,c=document)=>c.querySelector(s),$$=(s,c=document)=>[...c.querySelectorAll(s)],body=document.body,menu=$('#mobileMenu'),toast=$('#toast');let dirty=false;const showToast=m=>{toast.textContent=m;toast.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>toast.classList.remove('show'),2600)};const markDirty=()=>{dirty=true;$('.save-bar p').textContent='Ai modificări nesalvate.'};$('#menuOpen')?.addEventListener('click',()=>{menu.classList.add('open');menu.setAttribute('aria-hidden','false');body.style.overflow='hidden'});$('#menuClose')?.addEventListener('click',()=>{menu.classList.remove('open');menu.setAttribute('aria-hidden','true');body.style.overflow=''});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#menuClose')?.click()});$$('[data-toggle]').forEach(btn=>btn.addEventListener('click',()=>{btn.classList.toggle('on');btn.setAttribute('aria-pressed',btn.classList.contains('on'));markDirty()}));$$('[data-choice]').forEach(btn=>btn.addEventListener('click',()=>{$$('[data-choice]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');markDirty()}));$('#saveQuiet')?.addEventListener('click',()=>{markDirty();showToast('Intervalul silențios a fost actualizat.')});$('#enablePush')?.addEventListener('click',e=>{e.currentTarget.textContent='Activ';e.currentTarget.closest('.device').querySelector('.device-copy span').textContent='Dispozitivul curent · push activ';showToast('Notificările push au fost activate demonstrativ.');markDirty()});$$('[data-remove-device]').forEach(btn=>btn.addEventListener('click',()=>{btn.closest('.device')?.remove();showToast('Dispozitivul a fost eliminat.');markDirty()}));$('#testNotification')?.addEventListener('click',()=>{showToast('Notificare test: Canopy Run începe mâine la 10:30.')});$('#saveAll')?.addEventListener('click',()=>{dirty=false;$('.save-bar p').textContent='Preferințele sunt sincronizate.';showToast('Preferințele de notificare au fost salvate.')});if(!matchMedia('(prefers-reduced-motion: reduce)').matches){$$('.hero-copy > *').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],{duration:560,delay:50+i*65,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'}));$('.phone')?.animate([{opacity:0,transform:'translate(34px,24px) rotate(12deg) scale(.92)'},{opacity:1,transform:'translate(0,0) rotate(5deg) scale(1)'}],{duration:820,delay:170,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});$('.signal-card')?.animate([{opacity:0,transform:'translate(-20px,22px) rotate(-10deg)'},{opacity:1,transform:'translate(0,0) rotate(-5deg)'}],{duration:760,delay:280,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.animate([{opacity:0,transform:'translateY(14px)'},{opacity:1,transform:'translateY(0)'}],{duration:430,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});o.unobserve(e.target)}}),{threshold:.07});$$('.notification-group,.control-card,.summary-card').forEach(el=>o.observe(el))}})();</script>
<script>
(function(){
  function nvAuth(){ try { return JSON.parse(localStorage.getItem('nordvale_auth')||'null'); } catch(e){ return null; } }
  var a = nvAuth();
  if(!a || !a.token){ location.href='/autentificare?next='+encodeURIComponent(location.pathname+location.search); return; }
  var AH = { 'Authorization':'Bearer '+a.token };
  function api(ac,opt){ opt=opt||{}; opt.headers=Object.assign({},AH,opt.headers||{}); return fetch('/api/proxy.php?action='+ac,opt).then(function(r){return r.json().catch(function(){return{};});}).catch(function(){return{};}); }
  function post(ac,b){ return api(ac,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b||{})}); }
  function initials(n){ n=(n||'').trim(); if(!n)return 'N'; var p=n.split(/\s+/); return (((p[0]||'')[0]||'')+((p[1]||'')[0]||'')).toUpperCase()||'N'; }
  function hydrateUser(u){ if(!u)return; var name=u.name||(((u.first_name||'')+' '+(u.last_name||'')).trim())||'Cont Nordvale'; window.__nvName=name; var box=document.querySelector('.profile-mini'); if(box){ var av=box.querySelector('.avatar'); if(av)av.textContent=initials(name); var st=box.querySelector('strong'); if(st)st.textContent=name; var em=box.querySelector('strong + span'); if(em&&u.email)em.textContent=u.email; } }
  document.querySelectorAll('a,button').forEach(function(el){ if((el.textContent||'').trim()==='Deconectare'){ el.addEventListener('click',function(ev){ ev.preventDefault(); post('logout').finally(function(){ localStorage.removeItem('nordvale_auth'); location.href='/'; }); }); } });
  hydrateUser(a.user);
  api('me').then(function(d){ if(d&&d.success&&d.data){ a.user=Object.assign({},a.user,d.data); try{localStorage.setItem('nordvale_auth',JSON.stringify(a));}catch(e){} hydrateUser(a.user); } });
  api('acc-notifications').then(function(d){ if(!(d&&d.success&&Array.isArray(d.data)))return; var n=d.data.length; var sc=document.querySelector('.signal-card strong'); if(sc)sc.textContent=n+(n===1?' alertă utilă':' alerte utile'); });
})();
</script>
